(()=> {
'use strict';
const API=(window.__HATCHABLE__&&window.__HATCHABLE__.api)||'/api';
const $=s=>document.querySelector(s);
const all=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v==null?'':v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'","&#39;");
const state={user:null,profile:null,subscription:null,pane:'overview',activeConversationId:null,activeInterviewId:null,roadmaps:[],goals:[],learning:[],dsa:[],applications:[],dashboard:null};
function toast(message,isError){const el=$('#toast');if(!el)return;el.textContent=message;el.style.background=isError?'#fff0f0':'#e2f5e9';el.style.color=isError?'#a64449':'#215a3c';el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),3500)}
async function api(path,options={}){const o={...options,headers:{...(options.headers||{})}};if(o.body&&typeof o.body!=='string'){o.body=JSON.stringify(o.body);o.headers['Content-Type']='application/json'}let r;try{r=await fetch(API+path,o)}catch(e){throw Error('Network unavailable. Check your connection and retry.')}const d=await r.json().catch(()=>({error:'The server returned an unreadable response.'}));if(!r.ok){const er=Error(d.error||'Request failed ('+r.status+').');er.status=r.status;er.data=d;throw er}return d}
function statusBadge(status){const s=String(status||'unknown');const good=['completed','active','accepted','offer','solved','in_progress','ready'].includes(s);const warn=['todo','interested','preparing','applied','recruiter_screening','assessment','technical_interview','hiring_manager','final_round','needs_revision','not_started','paused'].includes(s);return '<span class="badge '+(good?'good':warn?'warn':'')+'">'+esc(s.replaceAll('_',' ').toUpperCase())+'</span>'}
function pageHead(kicker,title,desc,action){return '<div class="page-head"><div><div class="tiny-label">'+esc(kicker)+'</div><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div>'+(action?'<div class="page-actions">'+action+'</div>':'')+'</div>'}
function field(label,id,placeholder,type,opts){opts=opts||{};let input='',wide=opts.wide?' span-2':'';if(type==='textarea')input='<textarea id="'+id+'" '+(opts.required?'required':'')+' maxlength="'+(opts.max||4000)+'" placeholder="'+esc(placeholder||'')+'">'+esc(opts.value||'')+'</textarea>';else if(type==='select')input='<select id="'+id+'" '+(opts.required?'required':'')+'>'+opts.options.map(x=>'<option value="'+esc(x.value)+'" '+(opts.value===x.value?'selected':'')+'>'+esc(x.label)+'</option>').join('')+'</select>';else input='<input id="'+id+'" type="'+(type||'text')+'" '+(opts.required?'required':'')+' maxlength="'+(opts.max||300)+'" placeholder="'+esc(placeholder||'')+'" value="'+esc(opts.value||'')+'">';return '<div class="field'+wide+'"><label for="'+id+'">'+esc(label)+(opts.required?' *':'')+'</label>'+input+(opts.help?'<small class="help">'+esc(opts.help)+'</small>':'')+'</div>'}
function emptyState(title,desc,button,action){return '<div class="empty-state"><b>'+esc(title)+'</b><br>'+esc(desc)+(button?'<p><button class="btn btn-secondary btn-sm" data-pane="'+esc(action)+'">'+esc(button)+'</button></p>':'')+'</div>'}
function statCard(label,value,note){return '<div class="stat-card"><span>'+esc(label)+'</span><b>'+esc(value)+'</b><small>'+esc(note)+'</small></div>'}
function money(v){return v==null||v===''?'Not set':'₹'+Number(v).toLocaleString('en-IN')}
function dateText(v){return v?new Date(v).toLocaleDateString():'No date set'}
function goLogin(next){location.href='/login?next='+encodeURIComponent(next||'/')}
function publicStart(pane){if(state.user){openWorkspace(pane||'onboarding');return}goLogin('/'+(pane?'?pane='+encodeURIComponent(pane):''))}
function showMarketing(){state.pane='overview';$('#marketingView').classList.remove('hidden');$('#publicHeader').classList.remove('hidden');$('#appView').classList.add('hidden');all('.public-nav a').forEach(a=>a.onclick=()=>$('.public-nav').classList.remove('open'));$('#loginBtn').textContent='Log in';$('#getStarted').innerHTML='Build my career plan <span>↗</span>'}
async function renderPublicPricing(){const el=$('#publicPricing');if(!el)return;try{const d=await api('/pricing');el.innerHTML=d.plans.map(p=>'<article class="pricing-card '+(p.id==='pro'?'featured':'')+'"><div class="pricing-top"><span class="pricing-kicker">'+(p.id==='pro'?'CAREEROS PRO':'START WITH THE BASICS')+'</span>'+(p.id==='pro'?'<span class="recommended">MORE CAPACITY</span>':'')+'</div><h3>'+esc(p.name)+'</h3><p>'+esc(p.tagline)+'</p><div class="price">'+(Number(p.monthlyPriceInr)===0?'Free':'₹'+Number(p.monthlyPriceInr).toLocaleString('en-IN'))+(Number(p.monthlyPriceInr)===0?'':'<small> / month</small>')+'</div><div class="price-caption">'+Number(p.monthlyAiLimit)+' AI actions per month · proposed plan</div><ul class="pricing-features">'+p.features.map(f=>'<li>'+esc(f)+'</li>').join('')+'</ul><button class="btn '+(p.id==='pro'?'btn-primary':'btn-secondary')+'" data-pricing-cta="'+p.id+'">'+(p.id==='pro'?'Explore Pro':'Start free')+' <span>↗</span></button></article>').join('');all('[data-pricing-cta]').forEach(b=>b.onclick=()=>b.dataset.pricingCta==='pro'?publicStart('subscription'):publicStart('onboarding'))}catch(e){el.innerHTML='<div class="empty-state">Pricing is temporarily unavailable. Please refresh and retry.</div>'}}
async function refreshAuth(){const A=window.hatchable&&window.hatchable.auth;if(!A){state.user=null;showMarketing();return}try{const s=await A.getSession();state.user=s&&s.user||null}catch(e){state.user=null}if(state.user){$('#loginBtn').textContent='Open workspace';$('#getStarted').innerHTML='Open workspace ↗';$('#heroStart').innerHTML='Open my workspace <span>↗</span>'}else{$('#loginBtn').textContent='Log in';$('#getStarted').innerHTML='Build my career plan <span>↗</span>';$('#heroStart').innerHTML='Start your free account <span>↗</span>'}}
async function openWorkspace(pane){if(!state.user){goLogin(pane?'/'+(pane?'?pane='+encodeURIComponent(pane):''):'/');return}$('#marketingView').classList.add('hidden');$('#publicHeader').classList.add('hidden');$('#appView').classList.remove('hidden');$('#sideEmail').textContent=state.user.email||'Signed in';try{const [p,b]=await Promise.all([api('/profile'),api('/billing')]);state.profile=p.profile;state.subscription=b;$('#userLabel').textContent=(p.profile&&p.profile.full_name)||'My CareerOS';$('#userInitial').textContent=((p.profile&&p.profile.full_name)||state.user.email||'C').trim().slice(0,1).toUpperCase();$('#usageMiniTitle').textContent=(b.subscription&&b.subscription.plan_id==='pro'?'Pro':'Free')+' plan';$('#usageMiniSub').textContent=(b.usage&&b.usage.used||0)+' / '+(b.usage&&b.usage.limit||20)+' AI actions used';$('#usageMiniBar').style.width=Math.min(100,(b.usage&&b.usage.used||0)/Math.max(1,b.usage&&b.usage.limit||20)*100)+'%';const paneFromUrl=new URLSearchParams(location.search).get('pane');const next=pane||paneFromUrl||(!p.profile||!p.profile.onboarding_completed?'onboarding':'overview');await renderPane(next)}catch(e){toast(e.message,true);await renderPane('onboarding')}}
function signOut(){const A=window.hatchable&&window.hatchable.auth;if(A)A.signOut().catch(()=>{}).finally(()=>{state.user=null;state.profile=null;state.activeConversationId=null;state.activeInterviewId=null;showMarketing();window.scrollTo(0,0)});else showMarketing()}
function bindPaneButtons(root){root.querySelectorAll('[data-pane]').forEach(b=>b.addEventListener('click',()=>renderPane(b.dataset.pane)));root.querySelectorAll('[data-feature]').forEach(b=>b.addEventListener('click',()=>publicStart(b.dataset.feature==='interview'?'interviews':b.dataset.feature==='jobs'?'jobs':b.dataset.feature==='learning'?'learning':b.dataset.feature==='resume'?'resume':b.dataset.feature==='roadmap'?'roadmap':'coach')))}
function renderOnboarding(){const p=state.profile||{};return pageHead('PERSONALIZE CAREEROS',p.onboarding_completed?'Career profile':'Let’s map your next step',p.onboarding_completed?'Update your career context as your goals and experience change.':'Start with the essentials. You can edit this later and skip anything you do not know yet.')+'<form id="profileForm" class="panel"><h2 class="panel-title">Your career context</h2><p class="panel-subtitle">Only your account can access your career information.</p><div class="form-grid">'+field('Full name','profileName','Your name','text',{value:p.full_name||'',max:120})+field('Career stage','careerStage','','select',{required:true,value:p.career_stage||'working_professional',options:[{value:'student',label:'Student'},{value:'fresh_graduate',label:'Fresh graduate'},{value:'working_professional',label:'Working professional'},{value:'job_seeker',label:'Job seeker'},{value:'career_switcher',label:'Career switcher'},{value:'promotion_seeker',label:'Seeking promotion'}]})+field('Current role (optional)','currentRole','e.g. Backend Engineer','text',{value:p.current_role||'',max:160})+field('Experience (years)','experienceYears','0','number',{required:true,value:p.experience_years==null?'0':String(p.experience_years),max:4})+field('Target role','targetRole','What role are you working toward?','text',{required:true,value:p.target_role||'',max:160})+field('Weekly hours available','weeklyHours','e.g. 5','number',{required:true,value:p.weekly_hours||5,max:2,help:'Choose a realistic number, not an ideal week.'})+field('Current skills (comma-separated)','currentSkills','Node.js, SQL, DSA…','text',{value:Array.isArray(p.current_skills)?p.current_skills.join(', '):'',max:1200})+field('Education (optional)','education','Degree or relevant study','text',{value:p.education||'',max:400})+field('Preferred location','preferredLocation','City, country or remote','text',{value:p.preferred_location||'',max:160})+field('Work preference','workPreference','','select',{value:p.work_preference||'flexible',options:[{value:'onsite',label:'On-site'},{value:'hybrid',label:'Hybrid'},{value:'remote',label:'Remote'},{value:'flexible',label:'Flexible'}]})+field('Target date (optional)','targetDate','','date',{value:p.target_date?String(p.target_date).slice(0,10):''})+field('Learning style','learningStyle','','select',{value:p.learning_style||'mixed',options:[{value:'reading',label:'Reading'},{value:'videos',label:'Videos'},{value:'practice',label:'Practice problems'},{value:'projects',label:'Projects'},{value:'mixed',label:'A mix of methods'}]})+field('Strengths (optional)','strengths','What do you feel confident about? Separate with commas.','textarea',{value:Array.isArray(p.strengths)?p.strengths.join(', '):'',wide:true,max:1200})+field('Areas to improve (optional)','challengeAreas','Topics or skills that feel difficult. Separate with commas.','textarea',{value:Array.isArray(p.challenge_areas)?p.challenge_areas.join(', '):'',wide:true,max:1200})+field('Target companies (optional)','targetCompanies','Companies or industries, separated by commas','text',{value:Array.isArray(p.target_companies)?p.target_companies.join(', '):'',max:1000})+field('Certifications (optional)','certifications','Add real certifications, separated by commas','text',{value:Array.isArray(p.certifications)?p.certifications.join(', '):'',max:1000})+field('Salary expectation in INR (optional)','salaryExpectationInr','Optional numeric INR value','number',{value:p.salary_expectation_inr||'',max:15})+'</div><div class="form-actions"><button class="btn btn-primary" type="submit">Save my career profile <span>↗</span></button><button class="btn btn-secondary" type="button" data-pane="overview">Back to dashboard</button></div><p id="profileFormMsg" class="form-message" role="status"></p></form><p class="small-note">AI recommendations are advisory. Add only information you are comfortable storing in your private CareerOS workspace.</p>'}
async function renderOverview(){const d=await api('/dashboard');state.dashboard=d;if(d.emptyState)return renderOnboarding();const p=d.profile||{},tasks=d.todayTasks||[];let html=pageHead('YOUR CAREER COMMAND CENTER','Welcome back'+(p.full_name?', '+esc(p.full_name.split(' ')[0]):'')+'.','Your next steps, your current focus and your progress—based on saved account records.','<button class="btn btn-primary" data-pane="goals">＋ Add career goal</button>');html+='<div class="stat-grid">'+statCard('Career goals',Number(d.goals?.active||0),Number(d.goals?.completed||0)+' completed')+statCard('Roadmaps in progress',Number(d.roadmaps?.active||0),Number(d.tasks?.completed||0)+' tasks completed')+statCard('Active applications',Number(d.applications?.active||0),Number(d.applications?.total||0)+' tracked')+statCard('Mock interviews',Number(d.interviews?.completed||0),d.interviews?.average_score?'Average coaching score '+d.interviews.average_score+'/100':'No completed scores yet')+'</div>';html+='<div class="content-grid"><section class="panel"><h2 class="panel-title">Your career direction</h2><p class="panel-subtitle">Current context from your profile</p><div class="list-row"><span class="list-icon">↗</span><div class="list-copy"><b>'+esc(p.target_role||'Add a target role')+'</b><small>Target role · '+esc(p.career_stage||'career stage not set').replaceAll('_',' ')+'</small></div><button class="btn btn-secondary btn-sm" data-pane="settings">Edit profile</button></div><div class="list-row"><span class="list-icon">◷</span><div class="list-copy"><b>'+Number(p.weekly_hours||0)+' hours per week</b><small>Current planned learning capacity</small></div><span class="badge">'+esc(p.learning_style||'mixed')+'</span></div><div class="list-row"><span class="list-icon">✦</span><div class="list-copy"><b>AI actions this month</b><small>'+Number(d.aiUsage?.used||0)+' of '+Number(d.aiUsage?.limit||20)+' used on '+esc(d.aiUsage?.plan||'free')+' plan</small></div><button class="btn btn-secondary btn-sm" data-pane="subscription">Usage</button></div><div class="form-actions"><button class="btn btn-secondary btn-sm" data-pane="roadmap">Open roadmap ↗</button><button class="btn btn-secondary btn-sm" data-pane="coach">Ask your coach ↗</button></div></section><section class="panel"><h2 class="panel-title">Today’s recommended next actions</h2><p class="panel-subtitle">Tasks come from your saved roadmap.</p>';if(tasks.length)html+=tasks.map(t=>'<div class="task-card"><input type="checkbox" class="task-check" data-task-complete="'+t.id+'" '+(t.status==='completed'?'checked':'')+' aria-label="Complete '+esc(t.title)+'"><div class="task-detail"><b>'+esc(t.title)+'</b><small>'+esc(t.category)+' · '+Number(t.estimated_minutes||30)+' min · '+esc(t.priority)+' priority</small></div></div>').join('');else html+=emptyState('No tasks due today','Create a roadmap to turn your target role into practical tasks.','Create a roadmap','roadmap');html+='</section></div><section class="panel"><div class="page-head"><div><h2 class="panel-title">Daily interview question</h2><p class="panel-subtitle">A practice prompt to help you build a clearer answer. Use a real experience.</p></div><button class="btn btn-secondary btn-sm" data-pane="interviews">Start mock interview ↗</button></div><div class="interview-question"><small>'+esc(d.dailyQuestion?.category||'Practice')+'</small><p>'+esc(d.dailyQuestion?.question||'Explain a difficult problem you solved, the trade-offs you considered and how you checked the result.')+'</p></div><div class="form-actions"><button class="btn btn-primary btn-sm" data-pane="coach">Practice this with AI ↗</button><button class="btn btn-secondary btn-sm" data-pane="dsa">Open DSA practice ↗</button></div></section><div class="content-grid"><section class="panel"><h2 class="panel-title">Learning progress</h2><p class="panel-subtitle">Your saved learning topic statuses.</p><div class="list-row"><span class="list-icon">◇</span><div class="list-copy"><b>'+Number(d.learning?.completed||0)+' topics completed</b><small>'+Number(d.learning?.total||0)+' topics in progress or completed</small></div><button class="btn btn-secondary btn-sm" data-pane="learning">Open hub</button></div></section><section class="panel"><h2 class="panel-title">DSA progress</h2><p class="panel-subtitle">Attempts are tracked, not executed by CareerOS.</p><div class="list-row"><span class="list-icon">{ }</span><div class="list-copy"><b>'+Number(d.dsa?.solved||0)+' problems marked solved</b><small>'+Number(d.dsa?.total||0)+' attempts recorded</small></div><button class="btn btn-secondary btn-sm" data-pane="dsa">Practice DSA</button></div></section></div>';return html}
async function renderGoals(){const d=await api('/goals');state.goals=d.goals||[];let html=pageHead('CAREER STRATEGY','Career goals','Set a clear direction and use it to drive your roadmap. Goals are private to your account.','<button class="btn btn-primary" data-pane="roadmap">Build a roadmap ↗</button>');html+='<div class="content-grid"><section class="panel"><h2 class="panel-title">Add a goal</h2><p class="panel-subtitle">Start with an outcome you can influence.</p><form id="goalForm" class="form-grid">'+field('Goal title','goalTitle','e.g. Prepare for a backend engineering role','text',{required:true,max:180,wide:true})+field('Goal type','goalType','','select',{value:'new_role',options:[{value:'career_growth',label:'Career growth'},{value:'new_role',label:'New role'},{value:'promotion',label:'Promotion'},{value:'skill_building',label:'Skill building'},{value:'interview_prep',label:'Interview preparation'},{value:'career_switch',label:'Career switch'},{value:'portfolio',label:'Portfolio'}]})+field('Target date (optional)','goalDate','','date',{})+field('Target role (optional)','goalRole','Role or direction','text',{max:160,wide:true})+field('Description (optional)','goalDescription','Why does this goal matter?','textarea',{max:1500,wide:true})+'<div class="span-2"><button class="btn btn-primary" type="submit">Save goal</button><p id="goalFormMsg" class="form-message"></p></div></form></section><section class="panel"><h2 class="panel-title">Your goals</h2><p class="panel-subtitle">Update status as your priorities evolve.</p>';if(!state.goals.length)html+=emptyState('No goals yet','Add one clear goal to build a roadmap around it.');else html+=state.goals.map(g=>'<div class="list-row"><span class="list-icon">◎</span><div class="list-copy"><b>'+esc(g.title)+'</b><small>'+esc(g.goal_type.replaceAll('_',' '))+' · '+(g.target_date?esc(dateText(g.target_date)):'No deadline')+'</small>'+ (g.description?'<small>'+esc(g.description)+'</small>':'')+'</div><select data-goal-status="'+g.id+'" aria-label="Goal status">'+['active','paused','completed','archived'].map(s=>'<option value="'+s+'" '+(g.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select><button class="btn btn-secondary btn-sm" data-goal-delete="'+g.id+'">Delete</button></div>').join('');html+='</section></div>';return html}
async function renderRoadmaps(){const [rd,go]=await Promise.all([api('/roadmaps'),api('/goals')]);state.roadmaps=rd.roadmaps||[];state.goals=go.goals||[];const p=state.profile||{};let html=pageHead('CAREER ROADMAP','Make the next steps concrete.','Generate a realistic plan, then adjust it as life and work change. Completed tasks are preserved when you edit the roadmap.');html+='<section class="panel"><h2 class="panel-title">Create a roadmap</h2><p class="panel-subtitle">AI roadmaps use your profile as context. Generated tasks are suggestions, not guarantees.</p><form id="roadmapForm" class="form-grid">'+field('Target role','roadmapRole','Role you are working toward','text',{required:true,value:p.target_role||'',max:160})+field('Timeline (weeks)','roadmapWeeks','','select',{value:'4',options:[{value:'2',label:'2 weeks'},{value:'4',label:'4 weeks'},{value:'6',label:'6 weeks'},{value:'8',label:'8 weeks'},{value:'12',label:'12 weeks'},{value:'16',label:'16 weeks'}]})+field('Weekly hours','roadmapHours','Hours per week','number',{required:true,value:p.weekly_hours||5,max:2})+field('Link to a goal (optional)','roadmapGoal','','select',{value:'',options:[{value:'',label:'No linked goal'},...state.goals.filter(g=>g.status==='active').map(g=>({value:String(g.id),label:g.title}))]})+field('Roadmap title (optional)','roadmapTitle','e.g. SDE-2 30-day prep','text',{max:180})+field('Target date (optional)','roadmapDate','','date',{value:p.target_date?String(p.target_date).slice(0,10):''})+'<div class="field"><label for="roadmapAi">Generate with AI</label><select id="roadmapAi"><option value="true">AI-generated plan (uses AI quota)</option><option value="false">Starter plan without AI</option></select><small class="help">Use the starter plan if AI is unavailable or your monthly limit is reached.</small></div><div class="span-2"><button class="btn btn-primary" type="submit">Create my roadmap <span>↗</span></button><p id="roadmapFormMsg" class="form-message"></p></div></form></section><div style="margin-top:22px"><div class="page-head"><div><h2 class="panel-title">Your roadmaps</h2><p>Task changes are saved to your account.</p></div></div>';if(!state.roadmaps.length)html+=emptyState('Your roadmap begins here','Create a plan above to organize weekly goals and daily practice.');else html+=state.roadmaps.map(r=>'<section class="panel" style="margin-bottom:13px"><div class="page-head"><div><div class="tiny-label">'+esc(r.generated_by==='ai'?'AI-GENERATED DRAFT':'STARTER PLAN')+'</div><h2 class="panel-title" style="margin-top:8px">'+esc(r.title)+'</h2><p>'+esc(r.summary||'')+'</p><small class="small-note">'+esc(r.target_role||'Target role not set')+' · '+(r.target_date?esc(dateText(r.target_date)):'Flexible timeline')+' · '+statusBadge(r.status)+'</small></div><div class="page-actions"><button class="btn btn-secondary btn-sm" data-roadmap-status="'+r.id+'" data-status="'+(r.status==='paused'?'active':'paused')+'">'+(r.status==='paused'?'Resume':'Pause')+'</button><button class="btn btn-secondary btn-sm" data-roadmap-delete="'+r.id+'">Delete</button></div></div>'+renderRoadmapTasks(r.tasks||[])+'</section>').join('');html+='</div>';return html}
function renderRoadmapTasks(tasks){if(!tasks.length)return '<div class="empty-state">This roadmap has no tasks yet.</div>';const weeks=[...new Set(tasks.map(t=>Number(t.weekNumber||t.week_number||1)))].sort((a,b)=>a-b);return weeks.map(w=>'<div class="roadmap-week"><div class="roadmap-week-title">WEEK '+w+'</div>'+tasks.filter(t=>Number(t.weekNumber||t.week_number||1)===w).map(t=>'<div class="task-card"><input type="checkbox" class="task-check" data-task-complete="'+t.id+'" '+(t.status==='completed'?'checked':'')+' aria-label="Complete '+esc(t.title)+'"><div class="task-detail"><b>'+esc(t.title)+'</b><small>'+esc(t.category)+' · '+Number(t.estimatedMinutes||t.estimated_minutes||30)+' min · '+esc(t.priority)+' priority · Due '+esc(dateText(t.dueDate||t.due_date))+'</small>'+(t.description?'<p>'+esc(t.description)+'</p>':'')+(t.completionCriteria||t.completion_criteria?'<small>Done when: '+esc(t.completionCriteria||t.completion_criteria)+'</small>':'')+'</div>'+statusBadge(t.status)+'</div>').join('')+'</div>').join('')}
async function renderCoach(){const c=await api('/conversations');const conversations=c.conversations||[];if(!state.activeConversationId&&conversations.length)state.activeConversationId=Number(conversations[0].id);let messages=[];let current=null;if(state.activeConversationId){try{const d=await api('/coach?conversationId='+state.activeConversationId);messages=d.messages||[];current=d.conversation}catch(e){state.activeConversationId=null}}let html=pageHead('CAREER INTELLIGENCE','Your AI career coach','Ask about learning, interviews, resume improvements or a career move. Advice uses the profile context you have saved.');html+='<div class="chat-layout"><aside class="chat-sidebar"><button id="newConversation" class="btn btn-primary btn-sm">＋ New conversation</button>'+(conversations.length?conversations.map(x=>'<button class="conversation-button '+(Number(x.id)===Number(state.activeConversationId)?'active':'')+'" data-conversation="'+x.id+'">'+esc(x.title)+'</button>').join(''):emptyState('No conversations','Start a new conversation to save your coaching history.'))+'</aside><section class="chat-area"><div class="chat-topline"><div><b>'+esc(current?.title||'New career conversation')+'</b><br><small>Career guidance · AI-generated advice can be imperfect</small></div>'+(current?'<button class="btn btn-secondary btn-sm" id="deleteConversation">Delete</button>':'')+'</div><div id="chatMessages" class="chat-messages">'+(messages.length?messages.map(m=>'<div class="chat-message '+m.role+'">'+esc(m.content)+'</div>').join(''):'<div class="chat-empty"><b>What would you like to work on?</b><br>Start with a real goal, a difficult concept or a job description. CareerOS will help turn it into practical next steps.</div>')+'</div><div class="chat-prompts"><button data-coach-prompt="Create a 30-day preparation plan for my target role based on my weekly hours.">30-day preparation plan</button><button data-coach-prompt="Help me identify the next skill to improve for my target role.">Find my next skill</button><button data-coach-prompt="Ask me a behavioral interview question and help me improve my answer.">Practice behavioral interview</button></div><form id="coachForm" class="chat-composer"><textarea id="coachPrompt" rows="2" placeholder="Ask your career coach…" maxlength="12000" required></textarea><button class="btn btn-primary" type="submit">Send ↗</button></form><p id="coachMsg" class="form-message" style="padding:0 13px 10px"></p></section></div>';return html}
async function renderResume(){const d=await api('/resumes');const resumes=d.resumes||[],analyses=d.analyses||[];let html=pageHead('RESUME INTELLIGENCE','Resume Studio','Save a version, get specific feedback and improve achievement statements without inventing facts. PDF/DOCX parsing is not enabled; paste your resume text.')+'<div class="resume-layout"><section class="panel"><h2 class="panel-title">Save resume text</h2><p class="panel-subtitle">Text stays private to your account. You can edit it or delete it later.</p><form id="resumeSaveForm" class="form-grid">'+field('Resume title','resumeTitle','e.g. Backend Engineer Resume','text',{required:true,max:160})+field('Source file name (optional)','resumeSource','Resume.pdf (label only)','text',{max:240})+field('Resume text','resumeText','Paste resume text here. Do not add metrics or achievements you cannot verify.','textarea',{required:true,wide:true,max:30000})+'<div class="span-2"><button class="btn btn-primary" type="submit">Save resume version</button><p id="resumeSaveMsg" class="form-message"></p></div></form><div class="notice"><span>ⓘ</span><div>Direct file upload and PDF/DOCX extraction are not enabled in this release. The source filename is informational; the resume text is what gets analyzed.</div></div></section><section class="panel"><h2 class="panel-title">Analyze a resume</h2><p class="panel-subtitle">Choose a saved resume or paste the text below, then optionally add a job description.</p><form id="resumeAnalyzeForm" class="form-grid">'+field('Saved resume (optional)','resumePick','','select',{value:'',options:[{value:'',label:'Use pasted resume text instead'},...resumes.map(r=>({value:String(r.id),label:r.title+' · v'+r.version_number}))]})+field('Target role','resumeTargetRole','e.g. SDE-2 Backend Engineer','text',{max:160})+field('Resume text if not saved','resumeAnalyzeText','Paste resume text','textarea',{wide:true,max:30000})+field('Job description (optional)','resumeJobDescription','Paste the job description for role-specific feedback','textarea',{wide:true,max:16000})+'<div class="span-2"><button type="submit" class="btn btn-primary">Analyze resume <span>↗</span></button><p id="resumeAnalyzeMsg" class="form-message"></p></div></form></section></div><section class="panel" style="margin-top:14px"><h2 class="panel-title">Saved resumes</h2>';html+=resumes.length?resumes.map(r=>'<div class="list-row"><span class="list-icon">▤</span><div class="list-copy"><b>'+esc(r.title)+'</b><small>Version '+Number(r.version_number)+' · '+esc(r.source_name||'Pasted text')+' · Updated '+esc(dateText(r.updated_at))+'</small></div>'+statusBadge(r.status)+'<button class="btn btn-secondary btn-sm" data-resume-delete="'+r.id+'">Delete</button></div>').join(''):emptyState('No saved resume yet','Paste resume text above to keep a version in your workspace.');html+='</section><section class="panel" style="margin-top:14px"><h2 class="panel-title">Recent analyses</h2>';html+=analyses.length?analyses.map(a=>'<div class="list-row"><span class="list-icon">✦</span><div class="list-copy"><b>'+esc(a.target_role||'Resume review')+'</b><small>'+esc(dateText(a.created_at))+' · heuristic match score, not an ATS result</small></div><span class="score-chip">'+(a.estimated_match_score==null?'—':a.estimated_match_score)+'</span></div><details><summary class="link-quiet">View saved analysis</summary><pre class="json-result">'+esc(JSON.stringify(a.analysis,null,2))+'</pre></details>').join(''):emptyState('No analysis yet','Run an analysis to get strengths and actionable revisions.');html+='</section><section id="resumeAnalysisResult" class="panel hidden" style="margin-top:14px"><h2 class="panel-title">Analysis result</h2><p class="panel-subtitle">AI suggestions require your verification. The score is not a hiring prediction.</p><div id="resumeAnalysisBody"></div></section>';return html}
async function renderJobAnalysis(){const d=await api('/job-analysis');const saved=d.jobDescriptions||[],gaps=d.analyses||[];let html=pageHead('JOB INTELLIGENCE','Understand the role before you apply.','Paste a real job description to separate demonstrated skills from gaps and build a focused preparation plan.')+'<div class="content-grid"><section class="panel"><h2 class="panel-title">Analyze a job description</h2><p class="panel-subtitle">CareerOS compares this text with your saved profile. It does not fetch private recruiter data.</p><form id="jobAnalysisForm" class="form-grid">'+field('Job title','jobTitle','e.g. Senior Backend Engineer','text',{required:true,max:180})+field('Company (optional)','jobCompany','Company name','text',{max:160})+field('Source URL (optional)','jobUrl','https://careers.example.com/role','url',{max:500})+field('Job description','jobText','Paste the job description, responsibilities and requirements.','textarea',{required:true,wide:true,max:16000})+'<div class="span-2"><button type="submit" class="btn btn-primary">Analyze skill gaps <span>↗</span></button><p class="form-message" id="jobAnalysisMsg"></p></div></form></section><section class="panel"><h2 class="panel-title">Your saved job analyses</h2><p class="panel-subtitle">Revisit previous role comparisons.</p>';html+=saved.length?saved.map(j=>'<div class="list-row"><span class="list-icon">⌕</span><div class="list-copy"><b>'+esc(j.title)+'</b><small>'+esc(j.company||'Company not set')+' · '+esc(dateText(j.created_at))+'</small></div>'+statusBadge('saved')+'</div>').join(''):emptyState('No jobs analyzed yet','Paste a target role to identify what to practice next.');html+='</section></div><section id="jobAnalysisResult" class="panel hidden" style="margin-top:14px"><h2 class="panel-title">Skill-gap analysis</h2><div id="jobAnalysisBody"></div></section><section class="panel" style="margin-top:14px"><h2 class="panel-title">Previous analysis snapshots</h2>';html+=gaps.length?gaps.map(g=>'<details class="interview-turn"><summary>'+esc(g.target_role||'Role analysis')+' · '+esc(dateText(g.created_at))+'</summary><pre class="json-result">'+esc(JSON.stringify(g.analysis,null,2))+'</pre></details>').join(''):emptyState('No saved snapshots yet','Your next analysis will be saved here.');html+='</section>';return html}
async function renderInterviews(){const query=state.activeInterviewId?'?id='+encodeURIComponent(state.activeInterviewId):'';const d=await api('/interviews'+query);let html=pageHead('INTERVIEW PRACTICE','Practice before it counts.','Run AI-assisted question sessions and get structured coaching feedback. Scores are indicative practice signals, not hiring outcomes.');html+='<div class="content-grid"><section class="panel"><h2 class="panel-title">Start a mock interview</h2><p class="panel-subtitle">Choose a topic and difficulty for a sequential session.</p><form id="interviewStartForm" class="form-grid">'+field('Interview type','interviewType','','select',{value:'backend',options:[{value:'behavioral',label:'Behavioral / HR'},{value:'technical',label:'Technical fundamentals'},{value:'dsa',label:'DSA'},{value:'backend',label:'Backend engineering'},{value:'nodejs',label:'Node.js'},{value:'sql',label:'SQL and databases'},{value:'lld',label:'Low-level design'},{value:'hld',label:'High-level design'},{value:'system_design',label:'System design'},{value:'role_specific',label:'Role-specific'}]})+field('Difficulty','interviewDifficulty','','select',{value:'intermediate',options:[{value:'beginner',label:'Beginner'},{value:'intermediate',label:'Intermediate'},{value:'advanced',label:'Advanced'}]})+field('Target role','interviewRole','e.g. SDE-2 Backend Engineer','text',{value:(state.profile&&state.profile.target_role)||'',max:160})+field('Session title (optional)','interviewTitle','e.g. Node.js interview practice','text',{max:180})+'<div class="span-2"><button type="submit" class="btn btn-primary">Start interview <span>↗</span></button><p id="interviewStartMsg" class="form-message"></p></div></form></section><section class="panel"><h2 class="panel-title">Your interview history</h2><p class="panel-subtitle">Sessions and feedback are saved to your account.</p>';const sessions=d.sessions||[];html+=sessions.length?sessions.map(s=>'<div class="list-row"><span class="list-icon">◉</span><div class="list-copy"><b>'+esc(s.title)+'</b><small>'+esc(s.interview_type.replaceAll('_',' '))+' · '+Number(s.question_count||0)+' questions · '+esc(dateText(s.started_at))+'</small></div>'+statusBadge(s.status)+'<button class="btn btn-secondary btn-sm" data-interview-open="'+s.id+'">Open</button></div>').join(''):emptyState('No sessions yet','Start a mock interview to get your first question.');html+='</section></div>';const s=d.session;if(s){const turns=s.turns||[],last=turns[turns.length-1],pending=last&&!last.answer&&s.status==='in_progress';html+='<section class="panel" style="margin-top:14px"><div class="page-head"><div><h2 class="panel-title">'+esc(s.title)+'</h2><p>'+esc(s.interview_type.replaceAll('_',' '))+' · '+esc(s.difficulty)+' · '+esc(s.target_role||'Target role not set')+'</p></div><div class="page-actions">'+statusBadge(s.status)+'<button class="btn btn-secondary btn-sm" id="leaveInterview">Back to sessions</button></div></div>';html+=turns.map(t=>'<div class="interview-turn"><small class="tiny-label">QUESTION '+t.turn_number+'</small><h4>'+esc(t.question)+'</h4>'+(t.answer?'<p><b>Your answer</b><br>'+esc(t.answer)+'</p><details><summary>View AI feedback</summary><pre class="json-result">'+esc(JSON.stringify(t.evaluation,null,2))+'</pre></details>':'')+'</div>').join('');if(pending)html+='<form id="interviewAnswerForm" class="form-grid" style="margin-top:15px"><div class="field span-2"><label for="interviewAnswer">Your answer</label><textarea id="interviewAnswer" rows="7" maxlength="12000" required placeholder="Explain your reasoning, options, trade-offs and how you would validate the result."></textarea></div><div class="span-2 form-actions"><button type="submit" class="btn btn-primary">Submit answer & get feedback</button><button type="button" class="btn btn-secondary" id="finishInterview">Finish session</button></div><p class="form-message span-2" id="interviewAnswerMsg"></p></form>';if(s.status==='completed')html+='<div class="notice ok"><span>✓</span><div>Session complete. Overall coaching score: '+(s.score==null?'Not available':esc(s.score+'/100'))+'. Use the feedback to choose what to practice next.</div></div>';html+='</section>'}return html}
async function renderLearning(category){state.learningCategory=category||'';const path='/learning'+(category?'?category='+encodeURIComponent(category):'');const d=await api(path);state.learning=d.topics||[];let html=pageHead('LEARNING HUB','Build skills with intention.','Track learning topics, time spent and items to revise. Links marked verified come from the seeded catalog; CareerOS does not guarantee third-party resource availability.');html+='<div class="stat-grid">'+statCard('Topics',state.learning.length,'Catalog topics')+statCard('Completed',Number(d.stats?.completed||0),'Marked complete')+statCard('Started',Number(d.stats?.started||0),'Topics with saved progress')+statCard('Time recorded',Number(d.stats?.minutes||0)+' min','Time logged in learning progress')+'</div><div class="panel"><div class="page-head"><div><h2 class="panel-title">Learning topics</h2><p class="panel-subtitle">Pick one topic and keep your notes and time.</p></div><div class="page-actions"><select id="learningCategory"><option value="">All categories</option>'+['DSA','Backend','Databases','System Design','Career Skills'].map(c=>'<option value="'+esc(c)+'" '+(category===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></div></div><div class="topic-grid">';html+=state.learning.length?state.learning.map(t=>'<article class="topic-card"><div class="topic-top"><span>'+esc(t.category.toUpperCase())+'</span>'+statusBadge(t.progress_status)+'</div><h3>'+esc(t.title)+'</h3><p>'+esc(t.description)+'</p><div class="topic-top"><span>'+esc(t.difficulty)+' · '+Number(t.estimated_minutes||30)+' min</span>'+(t.resource_url?'<a class="link-quiet" href="'+esc(t.resource_url)+'" target="_blank" rel="noopener noreferrer">Resource ↗</a>':'')+'</div><div class="form-actions"><select aria-label="Progress for '+esc(t.title)+'" id="learnStatus-'+esc(t.slug)+'">'+['not_started','in_progress','completed','needs_revision'].map(s=>'<option value="'+s+'" '+(t.progress_status===s?'selected':'')+'>'+s.replaceAll('_',' ')+'</option>').join('')+'</select><button class="btn btn-secondary btn-sm" data-learning-save="'+esc(t.slug)+'">Save</button></div></article>').join(''):emptyState('No topics found','Try another category.');html+='</div></div>';return html}
async function renderDsa(){const d=await api('/dsa');state.dsa=d.problems||[];let html=pageHead('DSA PRACTICE','Build your problem-solving muscle.','Track attempts, approaches, complexity and revision needs. CareerOS does not execute submitted code in this release.');html+='<div class="stat-grid">'+statCard('Attempts',Number(d.stats?.attempts||0),'Saved attempts')+statCard('Marked solved',Number(d.stats?.solved||0),'Self-reported completion')+statCard('Problems attempted',Number(d.stats?.problems_attempted||0),'Unique problem records')+statCard('Code execution','Not enabled','Use a verified practice link to run solutions')+'</div><div class="notice"><span>ⓘ</span><div>'+esc(d.disclaimer)+'</div></div><section class="topic-grid">'+state.dsa.map(p=>'<article class="topic-card"><div class="topic-top"><span>'+esc(p.topic.toUpperCase())+'</span>'+statusBadge(p.difficulty)+'</div><h3>'+esc(p.title)+'</h3><p>'+esc(p.statement)+'</p><div class="topic-top"><span>'+esc(p.source||'Practice source')+(p.source_verified?' · source verified in catalog':' · unverified source')+'</span>'+(p.practice_url?'<a class="link-quiet" target="_blank" rel="noopener noreferrer" href="'+esc(p.practice_url)+'">Practice ↗</a>':'')+'</div><details style="margin-top:10px"><summary class="link-quiet">Record my attempt</summary><form class="dsa-attempt-form" data-dsa-slug="'+esc(p.slug)+'" style="margin-top:11px"><div class="field"><label>Status</label><select name="status"><option value="attempted">Attempted</option><option value="solved">Solved</option><option value="needs_revision">Needs revision</option><option value="skipped">Skipped</option></select></div><div class="field"><label>Language</label><input name="language" placeholder="C++, JavaScript…"></div><div class="field"><label>Time (minutes)</label><input name="actualMinutes" type="number" min="0" value="30"></div><div class="field"><label>Time complexity</label><input name="timeComplexity" placeholder="O(n)"></div><div class="field"><label>Space complexity</label><input name="spaceComplexity" placeholder="O(n)"></div><div class="field"><label>Approach notes</label><textarea name="approachNotes" rows="3"></textarea></div><button class="btn btn-primary btn-sm" type="submit">Save attempt</button><p class="form-message"></p></form></details></article>').join('')+'</section>';return html}
async function renderSystemDesign(){const d=await api('/learning?category=System%20Design');const topics=d.topics||[];let html=pageHead('SYSTEM DESIGN','Think in systems, not buzzwords.','Use this starter set to practice requirements, APIs, data models and trade-offs. Saved topic progress updates your learning record.','<button class="btn btn-primary" data-pane="coach">Practice with AI coach ↗</button>');html+='<div class="notice"><span>ⓘ</span><div>Each exercise is a preparation guide. Diagramming, collaborative whiteboards and voice interviews are not enabled in this release.</div></div><div class="topic-grid">';html+=topics.map(t=>'<article class="topic-card"><div class="topic-top"><span>'+esc(t.category.toUpperCase())+'</span>'+statusBadge(t.progress_status)+'</div><h3>'+esc(t.title)+'</h3><p>'+esc(t.description)+'</p><div class="topic-top"><span>'+esc(t.difficulty)+' · '+Number(t.estimated_minutes||45)+' min</span>'+(t.resource_url?'<a class="link-quiet" target="_blank" rel="noopener noreferrer" href="'+esc(t.resource_url)+'">Resource ↗</a>':'')+'</div><div class="form-actions"><select id="sd-status-'+esc(t.slug)+'" aria-label="Progress status"><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="needs_revision">Needs revision</option></select><button class="btn btn-secondary btn-sm" data-system-design-save="'+esc(t.slug)+'">Save progress</button></div></article>').join('');html+='</div><section class="panel" style="margin-top:16px"><h2 class="panel-title">Practice framework</h2><ol class="result-list"><li>Clarify functional and non-functional requirements.</li><li>Estimate users, throughput, storage and traffic growth.</li><li>Design API contracts and the core data model.</li><li>Sketch components and the request/event flow.</li><li>Discuss consistency, caches, queues, retries and idempotency.</li><li>Identify bottlenecks, failure modes, security and observability.</li><li>State trade-offs and describe what you would measure.</li></ol><button class="btn btn-secondary btn-sm" data-pane="coach">Ask the AI coach to interview me ↗</button></section>';return html}
async function renderJobs(){const d=await api('/applications');state.applications=d.applications||[];const statuses=['interested','preparing','applied','recruiter_screening','assessment','technical_interview','hiring_manager','final_round','offer','accepted','rejected','withdrawn'];let html=pageHead('CAREER EXECUTION','Keep every application moving.','Track companies, stages, interviews and follow-ups. Application records are private to your account.','<button class="btn btn-primary" id="jumpAddApplication">＋ Add application</button>');html+='<div class="stat-grid">'+statCard('Applications',Number(d.stats?.total||0),'All saved records')+statCard('Active pipeline',Number(d.stats?.active||0),'Not closed or withdrawn')+statCard('Offers',Number(d.stats?.offers||0),'Offer or accepted status')+statCard('Follow-ups due',state.applications.filter(a=>a.next_follow_up_at&&new Date(a.next_follow_up_at)<=new Date()).length,'Based on saved follow-up dates')+'</div><section class="panel" id="addApplicationPanel"><h2 class="panel-title">Add a job application</h2><p class="panel-subtitle">CareerOS does not fetch live listings in this release—add applications from a source you trust.</p><form id="applicationForm" class="form-grid">'+field('Company','appCompany','Company name','text',{required:true,max:160})+field('Job title','appTitle','Position title','text',{required:true,max:180})+field('Application URL (optional)','appUrl','https://careers.example.com/role','url',{max:600})+field('Location','appLocation','City / remote','text',{max:160})+field('Minimum salary (INR, optional)','appSalaryMin','Numeric amount','number',{max:15})+field('Maximum salary (INR, optional)','appSalaryMax','Numeric amount','number',{max:15})+field('Stage','appStatus','','select',{value:'interested',options:statuses.map(s=>({value:s,label:s.replaceAll('_',' ')}))})+field('Application date','appDate','','date')+field('Next follow-up (optional)','appFollowUp','','date')+field('Resume version used','appResumeVersion','e.g. Backend v3','text',{max:100})+field('Recruiter/contact (optional)','appRecruiter','Contact details or note','text',{max:240})+field('Notes','appNotes','Interview notes, requirements or next step','textarea',{wide:true,max:3000})+'<div class="span-2"><button type="submit" class="btn btn-primary">Save application</button><p class="form-message" id="applicationMsg"></p></div></form></section><section class="panel" style="margin-top:15px"><h2 class="panel-title">Your application pipeline</h2><p class="panel-subtitle">Change the stage or delete a record. Follow-up dates and notes stay editable.</p>';if(!state.applications.length)html+=emptyState('No job applications yet','Add a role you are interested in and keep its next action visible.');else{html+='<div class="application-board">';const columns=[['Interested','interested','preparing'],['In progress','applied','recruiter_screening','assessment','technical_interview'],['Final stages','hiring_manager','final_round','offer'],['Closed','accepted','rejected','withdrawn']];html+=columns.map(col=>'<div class="app-column"><h3>'+col[0]+' · '+state.applications.filter(a=>col.slice(1).includes(a.status)).length+'</h3>'+state.applications.filter(a=>col.slice(1).includes(a.status)).map(a=>'<div class="app-ticket"><b>'+esc(a.job_title)+'</b><small>'+esc(a.company)+' · '+esc(a.location||'Location not set')+'</small><small>'+(a.next_follow_up_at?'Follow up: '+esc(dateText(a.next_follow_up_at)):'No follow-up date')+'</small><select data-app-status="'+a.id+'" aria-label="Application status for '+esc(a.company)+'">'+statuses.map(s=>'<option value="'+s+'" '+(a.status===s?'selected':'')+'>'+s.replaceAll('_',' ')+'</option>').join('')+'</select><div class="form-actions"><button class="btn btn-secondary btn-sm" data-app-save="'+a.id+'">Save stage</button><button class="btn btn-secondary btn-sm" data-app-delete="'+a.id+'">Delete</button></div></div>').join('')+'</div>').join('')+'</div>'}html+='</section>';return html}
async function renderAnalytics(){const d=await api('/dashboard');state.dashboard=d;if(d.emptyState)return renderOnboarding();const p=d.profile||{},items=[['Career goal completion',Number(d.goals?.completed||0),Number(d.goals?.total||0)],['Roadmap tasks',Number(d.tasks?.completed||0),Number(d.tasks?.total||0)],['Learning topics completed',Number(d.learning?.completed||0),Number(d.learning?.total||0)],['DSA marked solved',Number(d.dsa?.solved||0),Number(d.dsa?.total||0)],['Interview sessions completed',Number(d.interviews?.completed||0),Number(d.interviews?.total||0)],['Applications active',Number(d.applications?.active||0),Number(d.applications?.total||0)]];let html=pageHead('YOUR PROGRESS','Measure the work you’ve done.','All figures below are calculated from your saved CareerOS records. Empty history means there is not enough personal data to draw a trend.');html+='<div class="stat-grid">'+statCard('Goals completed',Number(d.goals?.completed||0),'Of '+Number(d.goals?.total||0)+' goals')+statCard('Roadmap completion',Number(d.tasks?.completed||0)+' / '+Number(d.tasks?.total||0),'Tasks in saved roadmaps')+statCard('Interview average',d.interviews?.average_score?d.interviews.average_score+'/100':'—','AI coaching scores only')+statCard('AI actions used',Number(d.aiUsage?.used||0)+' / '+Number(d.aiUsage?.limit||20),'Current plan: '+(d.aiUsage?.plan||'free'))+'</div><div class="content-grid"><section class="panel"><h2 class="panel-title">Progress snapshots</h2><p class="panel-subtitle">Completion ratios use only saved records; they are not job outcome predictions.</p>';html+=items.map(i=>{const ratio=i[2]?Math.round(i[1]/i[2]*100):0;return '<div style="margin:16px 0"><div class="list-row" style="border:0;padding:0 0 7px"><span class="list-copy"><b>'+esc(i[0])+'</b><small>'+i[1]+' of '+i[2]+'</small></span><strong style="font:700 11px Manrope;color:#6578df">'+ratio+'%</strong></div><div style="height:6px;border-radius:7px;background:#e7eaf3;overflow:hidden"><div style="height:100%;width:'+ratio+'%;background:#7b8be7;border-radius:7px"></div></div></div>'}).join('');html+='</section><section class="panel"><h2 class="panel-title">What these metrics do—and don’t—say</h2><p class="panel-subtitle">Use the metrics to plan your week, not to judge your worth.</p><div class="list-row"><span class="list-icon">✓</span><div class="list-copy"><b>Progress is yours to define</b><small>Completed tasks and recorded attempts are self-reported activity.</small></div></div><div class="list-row"><span class="list-icon">✦</span><div class="list-copy"><b>AI scores are coaching signals</b><small>Interview and resume feedback is not a hiring decision or ATS result.</small></div></div><div class="list-row"><span class="list-icon">↻</span><div class="list-copy"><b>Review each week</b><small>Adjust workload and deadlines when work, health or life changes.</small></div></div><div class="form-actions"><button class="btn btn-secondary btn-sm" data-pane="roadmap">Review roadmap</button><button class="btn btn-secondary btn-sm" data-pane="subscription">View usage</button></div></section></div>';return html}
async function renderSubscription(){const d=await api('/billing');state.subscription=d;const s=d.subscription||{plan_id:'free',status:'active'},u=d.usage||{};let html=pageHead('PLAN & USAGE','Use CareerOS at your own pace.','Your current entitlements are enforced on the backend. Paid checkout is intentionally disabled until payment verification is implemented.');html+='<div class="content-grid"><section class="panel"><div class="tiny-label">CURRENT PLAN</div><h2 style="font:800 28px Manrope;margin:10px 0">'+esc((s.plan_id||'free').toUpperCase())+'</h2><p class="panel-subtitle">Status: '+esc(s.status)+' · Since '+esc(dateText(s.starts_at))+'</p><div class="stat-card"><span>AI actions used this month</span><b>'+Number(u.used||0)+' / '+Number(u.limit||20)+'</b><small>Limit is enforced server-side. Failed provider attempts may still count toward your monthly allowance.</small></div><div style="height:7px;border-radius:7px;background:#e7eaf4;overflow:hidden;margin-top:12px"><div style="height:100%;background:#7788e7;width:'+Math.min(100,Number(u.used||0)/Math.max(1,Number(u.limit||20))*100)+'%"></div></div></section><section class="panel"><h2 class="panel-title">Billing and checkout</h2><p class="panel-subtitle">'+esc(d.disclosure||'')+'</p><div class="notice"><span>ⓘ</span><div>Checkout is not enabled. No payment is being taken, and no upgrade is activated by a button click. A live gateway, signed webhook verification, invoices/refunds and entitlement tests are required before accepting subscriptions.</div></div></section></div><div class="pricing-grid" style="margin-top:15px">'+(d.plans||[]).map(p=>'<article class="pricing-card '+(p.id==='pro'?'featured':'')+'"><div class="pricing-top"><span class="pricing-kicker">'+(p.id==='pro'?'ADVANCED PREPARATION':'START HERE')+'</span></div><h3>'+esc(p.name)+'</h3><div class="price">'+(p.monthlyPriceInr?'₹'+Number(p.monthlyPriceInr).toLocaleString('en-IN'):'Free')+(p.monthlyPriceInr?'<small> / month</small>':'')+'</div><p>'+Number(p.monthlyAiLimit)+' AI actions each month.</p><ul class="pricing-features">'+p.features.map(f=>'<li>'+esc(f)+'</li>').join('')+'</ul><button class="btn '+(p.id==='pro'?'btn-primary':'btn-secondary')+'" '+(p.id==='pro'?'id="proCheckout"':'disabled')+'>'+(p.id==='pro'?'Upgrade unavailable':'Current free option')+'</button></article>').join('')+'</div>';return html}
async function renderSettings(){const p=state.profile||{};return pageHead('ACCOUNT & PRIVACY','Your career data belongs to you.','Review your profile, export your CareerOS application data, or permanently delete that data from this app.')+'<div class="content-grid"><section class="panel"><h2 class="panel-title">Profile settings</h2><p class="panel-subtitle">Keep your target role and available hours up to date.</p>'+renderOnboarding()+'</section><section class="panel"><h2 class="panel-title">Account and data controls</h2><p class="panel-subtitle">Signed in as '+esc(state.user?.email||'your account')+'.</p><div class="list-row"><span class="list-icon">⇩</span><div class="list-copy"><b>Export my data</b><small>Download a JSON file with your CareerOS profile, goals, conversations, resumes, interviews, learning progress and applications.</small></div><button class="btn btn-secondary btn-sm" id="exportData">Export JSON</button></div><div class="list-row"><span class="list-icon">⌫</span><div class="list-copy"><b>Delete CareerOS data</b><small>Deletes your CareerOS app records. This does not remove the underlying platform sign-in account.</small></div><button class="btn btn-secondary btn-sm" id="deleteData">Delete data</button></div><div class="notice"><span>ⓘ</span><div>Deletion is permanent. Export your records first if you may need them later. The platform authentication account is separate.</div></div><div class="form-actions"><button class="btn btn-secondary" id="settingsSignOut">Sign out</button></div></section></div>'}
async function renderPane(pane){state.pane=pane||'overview';const labels={overview:'Overview',onboarding:'Career profile',coach:'AI Career Coach',roadmap:'Career Roadmap',goals:'Goals',resume:'Resume Studio','job-analysis':'Job Description Analysis',interviews:'Mock Interviews',learning:'Learning Hub',dsa:'DSA Practice','system-design':'System Design',jobs:'Job Tracker',analytics:'Analytics',subscription:'Subscription',settings:'Settings & Privacy'};$('#paneLabel').textContent=labels[state.pane]||'Overview';all('.side-item').forEach(b=>b.classList.toggle('active',b.dataset.pane===state.pane));const root=$('#appContent');root.innerHTML='<div class="loading-block large"></div>';try{let html;if(state.pane==='overview')html=await renderOverview();else if(state.pane==='onboarding')html=renderOnboarding();else if(state.pane==='goals')html=await renderGoals();else if(state.pane==='roadmap')html=await renderRoadmaps();else if(state.pane==='coach')html=await renderCoach();else if(state.pane==='resume')html=await renderResume();else if(state.pane==='job-analysis')html=await renderJobAnalysis();else if(state.pane==='interviews')html=await renderInterviews();else if(state.pane==='learning')html=await renderLearning(state.learningCategory||'');else if(state.pane==='dsa')html=await renderDsa();else if(state.pane==='system-design')html=await renderSystemDesign();else if(state.pane==='jobs')html=await renderJobs();else if(state.pane==='analytics')html=await renderAnalytics();else if(state.pane==='subscription')html=await renderSubscription();else if(state.pane==='settings')html=await renderSettings();else html=await renderOverview();root.innerHTML=html;bindPaneButtons(root);bindPane(root);if(state.pane==='coach'){const m=$('#chatMessages');if(m)m.scrollTop=m.scrollHeight}$('#appSidebar').classList.remove('open')}catch(e){root.innerHTML='<div class="notice"><span>!</span><div>'+esc(e.message||'This section could not load.')+'</div></div><button class="btn btn-secondary" id="retryPane">Try again</button>';$('#retryPane').onclick=()=>renderPane(state.pane)}}
function bindPane(root){
 const profileForm=$('#profileForm');if(profileForm)profileForm.onsubmit=saveProfile;
 const goalForm=$('#goalForm');if(goalForm)goalForm.onsubmit=saveGoal;
 const roadmapForm=$('#roadmapForm');if(roadmapForm)roadmapForm.onsubmit=createRoadmap;
 const newConv=$('#newConversation');if(newConv)newConv.onclick=createConversation;
 root.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=async()=>{state.activeConversationId=Number(b.dataset.conversation);await renderPane('coach')});
 const coachForm=$('#coachForm');if(coachForm)coachForm.onsubmit=sendCoach;
 root.querySelectorAll('[data-coach-prompt]').forEach(b=>b.onclick=()=>{$('#coachPrompt').value=b.dataset.coachPrompt;$('#coachPrompt').focus()});
 const delConv=$('#deleteConversation');if(delConv)delConv.onclick=async()=>{if(!confirm('Delete this conversation and its messages?'))return;try{await api('/conversations',{method:'DELETE',body:{id:state.activeConversationId}});state.activeConversationId=null;toast('Conversation deleted');await renderPane('coach')}catch(e){toast(e.message,true)}};
 const resumeSave=$('#resumeSaveForm');if(resumeSave)resumeSave.onsubmit=saveResume;
 const resumeAnalysis=$('#resumeAnalyzeForm');if(resumeAnalysis)resumeAnalysis.onsubmit=analyzeResume;
 root.querySelectorAll('[data-resume-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this resume and its linked analyses?'))return;try{await api('/resumes',{method:'DELETE',body:{id:Number(b.dataset.resumeDelete)}});toast('Resume deleted');await renderPane('resume')}catch(e){toast(e.message,true)}});
 const jobForm=$('#jobAnalysisForm');if(jobForm)jobForm.onsubmit=analyzeJob;
 const interviewStart=$('#interviewStartForm');if(interviewStart)interviewStart.onsubmit=startInterview;
 root.querySelectorAll('[data-interview-open]').forEach(b=>b.onclick=async()=>{state.activeInterviewId=Number(b.dataset.interviewOpen);await renderPane('interviews')});
 const answerForm=$('#interviewAnswerForm');if(answerForm)answerForm.onsubmit=answerInterview;
 const leave=$('#leaveInterview');if(leave)leave.onclick=()=>{state.activeInterviewId=null;renderPane('interviews')};
 const finish=$('#finishInterview');if(finish)finish.onclick=async()=>{if(!confirm('End this interview without submitting the current answer? The session will be marked abandoned.'))return;try{await api('/interviews',{method:'PUT',body:{id:state.activeInterviewId,action:'abandon'}});toast('Interview ended');await renderPane('interviews')}catch(e){toast(e.message,true)}};
 const learnCat=$('#learningCategory');if(learnCat)learnCat.onchange=async()=>{state.learningCategory=learnCat.value;await renderPane('learning')};
 root.querySelectorAll('[data-learning-save]').forEach(b=>b.onclick=async()=>{try{await api('/learning',{method:'POST',body:{topicSlug:b.dataset.learningSave,status:$('#learnStatus-'+b.dataset.learningSave).value,timeSpentMinutes:0}});toast('Learning progress saved');await renderPane('learning')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-system-design-save]').forEach(b=>b.onclick=async()=>{try{await api('/learning',{method:'POST',body:{topicSlug:b.dataset.systemDesignSave,status:$('#sd-status-'+b.dataset.systemDesignSave).value,timeSpentMinutes:0}});toast('Progress saved');await renderPane('system-design')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('.dsa-attempt-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const data=new FormData(f);const msg=f.querySelector('.form-message');try{await api('/dsa',{method:'POST',body:{problemSlug:f.dataset.dsaSlug,status:data.get('status'),language:data.get('language'),approachNotes:data.get('approachNotes'),timeComplexity:data.get('timeComplexity'),spaceComplexity:data.get('spaceComplexity'),actualMinutes:data.get('actualMinutes')}});msg.textContent='Attempt saved.';toast('DSA attempt recorded');await renderPane('dsa')}catch(err){msg.textContent=err.message;msg.classList.add('error')}});
 const appForm=$('#applicationForm');if(appForm)appForm.onsubmit=saveApplication;
 const jump=$('#jumpAddApplication');if(jump)jump.onclick=()=>$('#addApplicationPanel').scrollIntoView({behavior:'smooth'});
 root.querySelectorAll('[data-app-save]').forEach(b=>b.onclick=async()=>{try{await api('/applications',{method:'PUT',body:{id:Number(b.dataset.appSave),status:$('#appStatus'+b.dataset.appSave)?$('#appStatus'+b.dataset.appSave).value:root.querySelector('[data-app-status="'+b.dataset.appSave+'"]').value}});toast('Application stage updated');await renderPane('jobs')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-app-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this job application?'))return;try{await api('/applications',{method:'DELETE',body:{id:Number(b.dataset.appDelete)}});toast('Application deleted');await renderPane('jobs')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-app-status]').forEach(s=>s.onchange=async()=>{const id=Number(s.dataset.appStatus);const b=root.querySelector('[data-app-save="'+id+'"]');if(b)b.dataset.appStatusPending=s.value});
 const exportBtn=$('#exportData');if(exportBtn)exportBtn.onclick=exportData;
 const deleteBtn=$('#deleteData');if(deleteBtn)deleteBtn.onclick=deleteData;
 const setOut=$('#settingsSignOut');if(setOut)setOut.onclick=signOut;
 const checkout=$('#proCheckout');if(checkout)checkout.onclick=()=>toast('Paid checkout is not enabled. No payment was taken.',true);
 root.querySelectorAll('[data-goal-status]').forEach(s=>s.onchange=async()=>{try{await api('/goals',{method:'PUT',body:{id:Number(s.dataset.goalStatus),status:s.value}});toast('Goal updated');await renderPane('goals')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-goal-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this goal? Any linked roadmap remains but will no longer point to this goal.'))return;try{await api('/goals',{method:'DELETE',body:{id:Number(b.dataset.goalDelete)}});toast('Goal deleted');await renderPane('goals')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-roadmap-status]').forEach(b=>b.onclick=async()=>{try{await api('/roadmaps',{method:'PUT',body:{id:Number(b.dataset.roadmapStatus),status:b.dataset.status}});toast('Roadmap status updated');await renderPane('roadmap')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-roadmap-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this roadmap and all its tasks?'))return;try{await api('/roadmaps',{method:'DELETE',body:{id:Number(b.dataset.roadmapDelete)}});toast('Roadmap deleted');await renderPane('roadmap')}catch(e){toast(e.message,true)}});
 root.querySelectorAll('[data-task-complete]').forEach(b=>b.onchange=async()=>{try{await api('/tasks',{method:'PUT',body:{id:Number(b.dataset.taskComplete),status:b.checked?'completed':'todo'}});toast(b.checked?'Task completed':'Task reopened');await renderPane(state.pane)}catch(e){toast(e.message,true);b.checked=!b.checked}});
 const settingsForm=root.querySelector('#profileForm');
}
async function renderLearningPage(category){state.pane='learning';await renderPane('learning')}
async function saveProfile(e){e.preventDefault();const msg=$('#profileFormMsg');msg.textContent='Saving your profile…';msg.classList.remove('error');const split=id=>$('#'+id).value.split(',').map(x=>x.trim()).filter(Boolean);const payload={fullName:$('#profileName').value,careerStage:$('#careerStage').value,currentRole:$('#currentRole').value,experienceYears:$('#experienceYears').value,targetRole:$('#targetRole').value,currentSkills:split('currentSkills'),education:$('#education').value,preferredLocation:$('#preferredLocation').value,workPreference:$('#workPreference').value,targetDate:$('#targetDate').value||null,weeklyHours:$('#weeklyHours').value,learningStyle:$('#learningStyle').value,strengths:split('strengths'),challengeAreas:split('challengeAreas'),targetCompanies:split('targetCompanies'),certifications:split('certifications'),salaryExpectationInr:$('#salaryExpectationInr').value||null};try{const d=await api('/profile',{method:'POST',body:payload});state.profile=d.profile;$('#userLabel').textContent=d.profile.full_name||'My CareerOS';$('#userInitial').textContent=(d.profile.full_name||state.user.email||'C').slice(0,1).toUpperCase();toast('Career profile saved');msg.textContent=d.message;await renderPane('overview')}catch(err){msg.textContent=err.message;msg.classList.add('error')}}
async function saveGoal(e){e.preventDefault();const msg=$('#goalFormMsg');try{await api('/goals',{method:'POST',body:{title:$('#goalTitle').value,goalType:$('#goalType').value,targetDate:$('#goalDate').value||null,targetRole:$('#goalRole').value,description:$('#goalDescription').value}});toast('Career goal saved');await renderPane('goals')}catch(err){msg.textContent=err.message;msg.classList.add('error')}}
async function createRoadmap(e){e.preventDefault();const msg=$('#roadmapFormMsg'),btn=e.submitter;if(btn)btn.disabled=true;try{const d=await api('/roadmaps',{method:'POST',body:{title:$('#roadmapTitle').value,targetRole:$('#roadmapRole').value,weeks:$('#roadmapWeeks').value,weeklyHours:$('#roadmapHours').value,goalId:$('#roadmapGoal').value||null,targetDate:$('#roadmapDate').value||null,useAI:$('#roadmapAi').value==='true'}});toast(d.message||'Roadmap created');await renderPane('roadmap')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
async function createConversation(){try{const d=await api('/conversations',{method:'POST',body:{title:'New conversation',contextType:'career_coach'}});state.activeConversationId=Number(d.conversation.id);await renderPane('coach');$('#coachPrompt')?.focus()}catch(e){toast(e.message,true)}}
async function sendCoach(e){e.preventDefault();const form=$('#coachForm'),prompt=$('#coachPrompt'),msg=$('#coachMsg'),btn=form.querySelector('button[type="submit"]');const text=prompt.value.trim();if(!text)return;btn.disabled=true;msg.textContent='Thinking…';msg.classList.remove('error');let id=state.activeConversationId;try{if(!id){const c=await api('/conversations',{method:'POST',body:{title:text.slice(0,64),contextType:'career_coach'}});id=Number(c.conversation.id);state.activeConversationId=id}const d=await api('/coach',{method:'POST',body:{conversationId:id,prompt:text}});prompt.value='';toast('Response saved to your conversation');await renderPane('coach')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{btn.disabled=false}}
async function saveResume(e){e.preventDefault();const msg=$('#resumeSaveMsg');msg.textContent='Saving resume text…';try{const d=await api('/resumes',{method:'POST',body:{title:$('#resumeTitle').value,sourceName:$('#resumeSource').value,rawText:$('#resumeText').value}});toast(d.message);await renderPane('resume')}catch(err){msg.textContent=err.message;msg.classList.add('error')}}
async function analyzeResume(e){e.preventDefault();const msg=$('#resumeAnalyzeMsg'),result=$('#resumeAnalysisResult'),body=$('#resumeAnalysisBody');msg.textContent='Analyzing resume…';msg.classList.remove('error');try{const d=await api('/resume-analysis',{method:'POST',body:{resumeId:$('#resumePick').value||null,targetRole:$('#resumeTargetRole').value,resumeText:$('#resumeAnalyzeText').value,jobDescription:$('#resumeJobDescription').value}});body.innerHTML=(d.analysis.estimatedMatchScore!=null?'<div class="score-chip">Estimated match '+esc(d.analysis.estimatedMatchScore)+'/100</div>':'')+'<p class="panel-subtitle">'+esc(d.disclaimer)+'</p><pre class="json-result">'+esc(JSON.stringify(d.analysis,null,2))+'</pre>';result.classList.remove('hidden');msg.textContent='Analysis saved.';toast('Resume analysis complete');result.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){msg.textContent=err.message;msg.classList.add('error')}}
async function analyzeJob(e){e.preventDefault();const msg=$('#jobAnalysisMsg'),result=$('#jobAnalysisResult'),body=$('#jobAnalysisBody');msg.textContent='Comparing the job with your profile…';msg.classList.remove('error');try{const d=await api('/job-analysis',{method:'POST',body:{title:$('#jobTitle').value,company:$('#jobCompany').value,sourceUrl:$('#jobUrl').value,jobDescription:$('#jobText').value}});body.innerHTML='<p class="panel-subtitle">'+esc(d.disclaimer)+'</p><pre class="json-result">'+esc(JSON.stringify(d.skillGap.analysis,null,2))+'</pre>';result.classList.remove('hidden');msg.textContent='Analysis saved.';toast('Job description analyzed');result.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){msg.textContent=err.message;msg.classList.add('error')}}
async function startInterview(e){e.preventDefault();const msg=$('#interviewStartMsg'),btn=e.submitter;if(btn)btn.disabled=true;msg.textContent='Preparing the first question…';try{const d=await api('/interviews',{method:'POST',body:{action:'start',interviewType:$('#interviewType').value,difficulty:$('#interviewDifficulty').value,targetRole:$('#interviewRole').value,title:$('#interviewTitle').value}});state.activeInterviewId=Number(d.session.id);toast('Interview session started');await renderPane('interviews')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
async function answerInterview(e){e.preventDefault();const msg=$('#interviewAnswerMsg'),btn=e.submitter;const d=await api('/interviews?id='+state.activeInterviewId);const session=d.session,turns=session&&session.turns||[],last=turns[turns.length-1];if(!last){msg.textContent='No pending question found.';return}if(btn)btn.disabled=true;msg.textContent='Evaluating your answer…';try{const r=await api('/interviews',{method:'POST',body:{action:'answer',sessionId:state.activeInterviewId,turnId:last.id,answer:$('#interviewAnswer').value}});toast('Feedback saved');await renderPane('interviews')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
async function saveApplication(e){e.preventDefault();const msg=$('#applicationMsg');msg.textContent='Saving application…';try{await api('/applications',{method:'POST',body:{company:$('#appCompany').value,jobTitle:$('#appTitle').value,applicationUrl:$('#appUrl').value,location:$('#appLocation').value,salaryMinInr:$('#appSalaryMin').value||null,salaryMaxInr:$('#appSalaryMax').value||null,status:$('#appStatus').value,applicationDate:$('#appDate').value||null,nextFollowUpAt:$('#appFollowUp').value||null,resumeVersion:$('#appResumeVersion').value,recruiterContact:$('#appRecruiter').value,notes:$('#appNotes').value}});toast('Application saved');await renderPane('jobs')}catch(err){msg.textContent=err.message;msg.classList.add('error')}}
async function exportData(){const btn=$('#exportData');if(btn)btn.disabled=true;try{const d=await api('/data');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='careeros-data-export-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Data export prepared. Keep it private.')}catch(e){toast(e.message,true)}finally{if(btn)btn.disabled=false}}
async function deleteData(){const confirmation=prompt('This permanently deletes your CareerOS application records. To continue, type exactly: DELETE MY CAREER DATA');if(confirmation!=='DELETE MY CAREER DATA'){toast('Deletion cancelled');return}try{await api('/data',{method:'DELETE',body:{confirmation}});state.profile=null;state.activeConversationId=null;state.activeInterviewId=null;toast('CareerOS application data deleted');await renderPane('onboarding')}catch(e){toast(e.message,true)}}
function bindGlobals(){all('.side-item').forEach(b=>b.onclick=()=>renderPane(b.dataset.pane));$('#sideToggle').onclick=()=>$('#appSidebar').classList.toggle('open');$('#getStarted').onclick=()=>publicStart('onboarding');$('#heroStart').onclick=()=>publicStart('onboarding');$('#quoteCta').onclick=()=>publicStart('onboarding');$('#faqStart').onclick=()=>publicStart('onboarding');$('#loginBtn').onclick=()=>state.user?openWorkspace('overview'):goLogin('/');$('#mobileMenu').onclick=()=>$('.public-nav').classList.toggle('open');all('.public-nav a').forEach(a=>a.addEventListener('click',()=>$('.public-nav').classList.remove('open')));all('[data-feature]').forEach(b=>b.onclick=()=>publicStart(b.dataset.feature==='interview'?'interviews':b.dataset.feature==='jobs'?'jobs':b.dataset.feature==='learning'?'learning':b.dataset.feature==='resume'?'resume':b.dataset.feature==='roadmap'?'roadmap':'coach'));$('#quickAction').onclick=()=>renderPane('goals');$('#signOutBtn').onclick=signOut;window.addEventListener('hashchange',()=>{$('.public-nav')?.classList.remove('open')})}
async function init(){if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});bindGlobals();await refreshAuth();renderPublicPricing();if(state.user){const p=new URLSearchParams(location.search).get('pane');await openWorkspace(p||'overview')}else showMarketing()}
init();
})();